/* Restore missing barcode decoder. Images are decoded locally on the device. */
(() => {
  'use strict';
  const sources = [
    'https://cdn.jsdelivr.net/npm/@zxing/browser@0.1.5/umd/zxing-browser.min.js',
    'https://unpkg.com/@zxing/browser@0.1.5/umd/zxing-browser.min.js'
  ];
  function load(index) {
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = sources[index];
      const timeout = setTimeout(() => { script.remove(); reject(new Error('Scanner timed out')); }, 10000);
      script.onload = () => {
        clearTimeout(timeout);
        window.ZXingBrowser?.BrowserMultiFormatReader ? resolve(true) : reject(new Error('Decoder did not initialize'));
      };
      script.onerror = () => { clearTimeout(timeout); reject(new Error('Decoder CDN unavailable')); };
      document.head.append(script);
    }).catch(error => index + 1 < sources.length ? load(index + 1) : Promise.reject(error));
  }
  window.kartochkaScannerReady = load(0).catch(() => false);
  const enhancement = document.createElement('script');
  enhancement.src = './scanner-enhance.js';
  enhancement.onerror = () => console.warn('Kartochka scanner enhancement could not be loaded');
  document.head.append(enhancement);
})();